index 00000000..b91ce1d7
--- /dev/null
+++ b/durability.go
@@ -0,0 +1,402 @@
+// Copyright 2024 The LevelDB-Go and Pebble Authors. All rights reserved. Use
+// of this source code is governed by a BSD-style license that can be found in
+// the LICENSE file.
+
+package pebble
+
+import (
+	"context"
+	"sync"
+	"sync/atomic"
+	"time"
+
+	"github.com/cockroachdb/errors"
+	"github.com/cockroachdb/pebble/internal/base"
+)
+
+const (
+	maxDurabilitySubscriptions = 10000
+	maxRetainedDurabilityJobs  = 10000
+)
+
+// DurabilityStats contains statistics about DB commits and durability waiting.
+type DurabilityStats struct {
+	HighestDurableSeqNum   base.SeqNum
+	FirstErr               error
+	PendingWaiters         int64
+	TotalDurableCommits    uint64
+	TotalFailedCommits     uint64
+	CumulativeSyncDuration time.Duration
+	MaxSyncDuration        time.Duration
+}
+
+type durabilitySub struct {
+	seq base.SeqNum
+	ch  chan error
+}
+
+type durabilityManager struct {
+	mu                     sync.Mutex
+	notifyCh               chan struct{}
+	highestDurableSeqNum   base.SeqNum
+	firstErr               error
+	pendingWaiters         atomic.Int64
+	totalDurableCommits    uint64
+	totalFailedCommits     uint64
+	cumulativeSyncDuration time.Duration
+	maxSyncDuration        time.Duration
+
+	// Accumulated metrics
+	durableCommitCount     atomic.Uint64
+	durableCommitDuration  atomic.Int64 // nanoseconds
+	batchDurableConfigured bool
+
+	// Subscriptions for DurabilityNotify
+	subscriptions map[uint64]*durabilitySub
+	nextSubID     uint64
+
+	// Job tracking
+	highestAllocatedJobID int
+	minRetainedJobID      int
+	nextJobID             int
+	retainedJobs          map[int]error
+	pendingJobChans       map[int]chan struct{}
+
+	closed bool
+}
+
+func newDurabilityManager(batchDurableConfigured bool) *durabilityManager {
+	m := &durabilityManager{
+		notifyCh:               make(chan struct{}),
+		batchDurableConfigured: batchDurableConfigured,
+		subscriptions:          make(map[uint64]*durabilitySub),
+		retainedJobs:           make(map[int]error),
+		pendingJobChans:        make(map[int]chan struct{}),
+		minRetainedJobID:       1,
+		nextJobID:              1,
+	}
+	return m
+}
+
+func (m *durabilityManager) allocateJobID() int {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+	id := m.nextJobID
+	m.nextJobID++
+	if id > m.highestAllocatedJobID {
+		m.highestAllocatedJobID = id
+	}
+	return id
+}
+
+func (m *durabilityManager) recordJobAllocated(jobID int) {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+	if jobID > m.highestAllocatedJobID {
+		m.highestAllocatedJobID = jobID
+	}
+}
+
+func (m *durabilityManager) onCommitDurable(info BatchDurableInfo, batchDurableFn func(BatchDurableInfo)) {
+	if batchDurableFn != nil {
+		batchDurableFn(info)
+	}
+
+	m.mu.Lock()
+	defer m.mu.Unlock()
+
+	if info.Err != nil {
+		m.totalFailedCommits++
+		if m.firstErr == nil {
+			m.firstErr = info.Err
+		}
+	} else {
+		m.totalDurableCommits++
+		m.cumulativeSyncDuration += info.SyncDuration
+		if info.SyncDuration > m.maxSyncDuration {
+			m.maxSyncDuration = info.SyncDuration
+		}
+		endSeq := info.SeqNum + base.SeqNum(info.KeyCount)
+		if endSeq > m.highestDurableSeqNum {
+			m.highestDurableSeqNum = endSeq
+		}
+	}
+
+	if m.batchDurableConfigured {
+		m.durableCommitCount.Add(1)
+		m.durableCommitDuration.Add(int64(info.SyncDuration))
+	}
+
+	// Record job result
+	if info.JobID > 0 {
+		if info.JobID > m.highestAllocatedJobID {
+			m.highestAllocatedJobID = info.JobID
+		}
+		m.retainedJobs[info.JobID] = info.Err
+		if ch, ok := m.pendingJobChans[info.JobID]; ok {
+			close(ch)
+			delete(m.pendingJobChans, info.JobID)
+		}
+		for len(m.retainedJobs) > maxRetainedDurabilityJobs {
+			delete(m.retainedJobs, m.minRetainedJobID)
+			m.minRetainedJobID++
+		}
+	}
+
+	// Process notify subscriptions
+	for id, sub := range m.subscriptions {
+		if sub.seq <= m.highestDurableSeqNum || m.firstErr != nil {
+			sub.ch <- m.firstErr
+			delete(m.subscriptions, id)
+		}
+	}
+
+	// Notify all waiters
+	oldNotify := m.notifyCh
+	m.notifyCh = make(chan struct{})
+	close(oldNotify)
+}
+
+func (m *durabilityManager) onClose(err error) {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+
+	m.closed = true
+	if m.firstErr == nil {
+		if err != nil {
+			m.firstErr = err
+		} else {
+			m.firstErr = ErrClosed
+		}
+	}
+
+	for id, sub := range m.subscriptions {
+		sub.ch <- m.firstErr
+		delete(m.subscriptions, id)
+	}
+
+	for jobID, ch := range m.pendingJobChans {
+		close(ch)
+		delete(m.pendingJobChans, jobID)
+	}
+
+	oldNotify := m.notifyCh
+	m.notifyCh = make(chan struct{})
+	close(oldNotify)
+}
+
+func (m *durabilityManager) durableState() (base.SeqNum, error) {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+	return m.highestDurableSeqNum, m.firstErr
+}
+
+func (m *durabilityManager) durabilityStats() DurabilityStats {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+	return DurabilityStats{
+		HighestDurableSeqNum:   m.highestDurableSeqNum,
+		FirstErr:               m.firstErr,
+		PendingWaiters:         m.pendingWaiters.Load(),
+		TotalDurableCommits:    m.totalDurableCommits,
+		TotalFailedCommits:     m.totalFailedCommits,
+		CumulativeSyncDuration: m.cumulativeSyncDuration,
+		MaxSyncDuration:        m.maxSyncDuration,
+	}
+}
+
+func (m *durabilityManager) durabilityNotify(seq base.SeqNum, disableWAL bool) <-chan error {
+	ch := make(chan error, 1)
+	if disableWAL {
+		ch <- nil
+		return ch
+	}
+
+	m.mu.Lock()
+	defer m.mu.Unlock()
+
+	if seq <= m.highestDurableSeqNum {
+		ch <- m.firstErr
+		return ch
+	}
+	if m.firstErr != nil {
+		ch <- m.firstErr
+		return ch
+	}
+	if len(m.subscriptions) >= maxDurabilitySubscriptions {
+		ch <- errors.New("pebble: excess durability notify subscriptions")
+		return ch
+	}
+
+	m.nextSubID++
+	id := m.nextSubID
+	m.subscriptions[id] = &durabilitySub{seq: seq, ch: ch}
+	return ch
+}
+
+func (m *durabilityManager) waitForDurability(ctx context.Context, seq base.SeqNum, disableWAL bool) error {
+	if disableWAL {
+		return nil
+	}
+
+	m.pendingWaiters.Add(1)
+	defer m.pendingWaiters.Add(-1)
+
+	m.mu.Lock()
+	defer m.mu.Unlock()
+
+	for {
+		if seq == 0 {
+			if m.totalDurableCommits > 0 || m.highestDurableSeqNum > 0 {
+				return m.firstErr
+			}
+		} else {
+			if m.highestDurableSeqNum >= seq {
+				return m.firstErr
+			}
+		}
+
+		if m.firstErr != nil || m.closed {
+			return m.firstErr
+		}
+
+		if ctx.Err() != nil {
+			return ctx.Err()
+		}
+
+		notify := m.notifyCh
+		m.mu.Unlock()
+
+		select {
+		case <-notify:
+			m.mu.Lock()
+		case <-ctx.Done():
+			m.mu.Lock()
+			// Durability or DB close errors take precedence over context cancellation
+			if seq == 0 {
+				if m.totalDurableCommits > 0 || m.highestDurableSeqNum > 0 {
+					return m.firstErr
+				}
+			} else {
+				if m.highestDurableSeqNum >= seq {
+					return m.firstErr
+				}
+			}
+			if m.firstErr != nil || m.closed {
+				return m.firstErr
+			}
+			return ctx.Err()
+		}
+	}
+}
+
+func (m *durabilityManager) waitForJobDurability(ctx context.Context, jobID int, disableWAL bool) error {
+	if disableWAL {
+		return nil
+	}
+
+	if jobID <= 0 {
+		return errors.Errorf("durability job %d: unknown job ID", jobID)
+	}
+
+	m.pendingWaiters.Add(1)
+	defer m.pendingWaiters.Add(-1)
+
+	m.mu.Lock()
+	defer m.mu.Unlock()
+
+	for {
+		if jobID > m.highestAllocatedJobID {
+			return errors.Errorf("durability job %d: unknown job ID", jobID)
+		}
+		if jobID < m.minRetainedJobID {
+			return errors.Errorf("durability job %d: expired job ID", jobID)
+		}
+
+		if err, ok := m.retainedJobs[jobID]; ok {
+			return err
+		}
+
+		if m.firstErr != nil || m.closed {
+			return m.firstErr
+		}
+
+		if ctx.Err() != nil {
+			return ctx.Err()
+		}
+
+		notify := m.notifyCh
+		m.mu.Unlock()
+
+		select {
+		case <-notify:
+			m.mu.Lock()
+		case <-ctx.Done():
+			m.mu.Lock()
+			if err, ok := m.retainedJobs[jobID]; ok {
+				return err
+			}
+			if jobID < m.minRetainedJobID {
+				return errors.Errorf("durability job %d: expired job ID", jobID)
+			}
+			if m.firstErr != nil || m.closed {
+				return m.firstErr
+			}
+			return ctx.Err()
+		}
+	}
+}
+
+// WaitForDurability blocks until sequence number seq is durable.
+func (d *DB) WaitForDurability(seq base.SeqNum) error {
+	return d.durability.waitForDurability(context.Background(), seq, d.opts.DisableWAL)
+}
+
+// WaitForDurabilityContext blocks until sequence number seq is durable or ctx is done.
+func (d *DB) WaitForDurabilityContext(ctx context.Context, seq base.SeqNum) error {
+	return d.durability.waitForDurability(ctx, seq, d.opts.DisableWAL)
+}
+
+// WaitForDurabilityBatch blocks until every sequence number in seqs is durable.
+func (d *DB) WaitForDurabilityBatch(seqs []base.SeqNum) error {
+	return d.WaitForDurabilityBatchContext(context.Background(), seqs)
+}
+
+// WaitForDurabilityBatchContext blocks until every sequence number in seqs is durable or ctx is done.
+func (d *DB) WaitForDurabilityBatchContext(ctx context.Context, seqs []base.SeqNum) error {
+	if len(seqs) == 0 {
+		return nil
+	}
+	var maxSeq base.SeqNum
+	for _, s := range seqs {
+		if s > maxSeq {
+			maxSeq = s
+		}
+	}
+	return d.durability.waitForDurability(ctx, maxSeq, d.opts.DisableWAL)
+}
+
+// WaitForJobDurability blocks until jobID is durable.
+func (d *DB) WaitForJobDurability(jobID int) error {
+	return d.durability.waitForJobDurability(context.Background(), jobID, d.opts.DisableWAL)
+}
+
+// WaitForJobDurabilityContext blocks until jobID is durable or ctx is done.
+func (d *DB) WaitForJobDurabilityContext(ctx context.Context, jobID int) error {
+	return d.durability.waitForJobDurability(ctx, jobID, d.opts.DisableWAL)
+}
+
+// DurableState returns the highest durable sequence number and first latched error.
+func (d *DB) DurableState() (base.SeqNum, error) {
+	return d.durability.durableState()
+}
+
+// DurabilityNotify returns a receive-only channel that delivers nil on success or a non-nil error.
+func (d *DB) DurabilityNotify(seq base.SeqNum) <-chan error {
+	return d.durability.durabilityNotify(seq, d.opts.DisableWAL)
+}
+
+// DurabilityStats returns a snapshot of durability statistics.
+func (d *DB) DurabilityStats() DurabilityStats {
+	return d.durability.durabilityStats()
+}
