+// Copyright 2024 The LevelDB-Go and Pebble Authors. All rights reserved. Use
+// of this source code is governed by a BSD-style license that can be found in
+// the LICENSE file.
+
+package pebble
+
+import (
+	"context"
+	"strings"
+	"sync"
+	"testing"
+	"time"
+
+	"github.com/cockroachdb/crlib/testutils/leaktest"
+	"github.com/cockroachdb/pebble/internal/base"
+	"github.com/cockroachdb/pebble/vfs"
+	"github.com/stretchr/testify/require"
+)
+
+func TestBatchDurable(t *testing.T) {
+	defer leaktest.AfterTest(t)()
+
+	var events []BatchDurableInfo
+	var mu sync.Mutex
+
+	opts := &Options{
+		FS: vfs.NewMem(),
+		EventListener: &EventListener{
+			BatchDurable: func(info BatchDurableInfo) {
+				mu.Lock()
+				events = append(events, info)
+				mu.Unlock()
+			},
+		},
+	}
+
+	d, err := Open("", opts)
+	require.NoError(t, err)
+	defer d.Close()
+
+	// 1. Sync commit
+	writeOpts := &WriteOptions{
+		Sync:                true,
+		CommitCorrelationID: 42,
+	}
+	b1 := d.NewBatch()
+	require.NoError(t, b1.Set([]byte("k1"), []byte("v1"), nil))
+	require.NoError(t, d.Apply(b1, writeOpts))
+
+	// 2. Non-sync commit (must NOT trigger BatchDurable)
+	b2 := d.NewBatch()
+	require.NoError(t, b2.Set([]byte("k2"), []byte("v2"), nil))
+	require.NoError(t, d.Apply(b2, NoSync))
+
+	mu.Lock()
+	count := len(events)
+	mu.Unlock()
+	require.Equal(t, 1, count)
+
+	info := events[0]
+	require.Equal(t, uint64(42), info.CorrelationID)
+	require.Greater(t, info.JobID, 0)
+	require.NoError(t, info.Err)
+	require.Greater(t, info.ApplyDuration, time.Duration(0))
+	require.Greater(t, info.SyncDuration, time.Duration(0))
+	require.Equal(t, uint32(1), info.KeyCount)
+	require.Greater(t, info.BatchSize, 0)
+
+	// Metrics check
+	m := d.Metrics()
+	require.Equal(t, uint64(1), m.DurableCommitCount)
+	require.Greater(t, m.DurableCommitDuration, time.Duration(0))
+}
+
+func TestBatchDurableMetricsNotConfigured(t *testing.T) {
+	defer leaktest.AfterTest(t)()
+
+	opts := &Options{
+		FS: vfs.NewMem(),
+	}
+
+	d, err := Open("", opts)
+	require.NoError(t, err)
+	defer d.Close()
+
+	b := d.NewBatch()
+	require.NoError(t, b.Set([]byte("k1"), []byte("v1"), nil))
+	require.NoError(t, d.Apply(b, Sync))
+
+	m := d.Metrics()
+	require.Equal(t, uint64(0), m.DurableCommitCount)
+	require.Equal(t, time.Duration(0), m.DurableCommitDuration)
+}
+
+func TestWaitForDurability(t *testing.T) {
+	defer leaktest.AfterTest(t)()
+
+	d, err := Open("", &Options{FS: vfs.NewMem()})
+	require.NoError(t, err)
+	defer d.Close()
+
+	// Before any commits, stats start at zero
+	stats := d.DurabilityStats()
+	require.Equal(t, base.SeqNum(0), stats.HighestDurableSeqNum)
+	require.Equal(t, uint64(0), stats.TotalDurableCommits)
+
+	b := d.NewBatch()
+	require.NoError(t, b.Set([]byte("foo"), []byte("bar"), nil))
+	require.NoError(t, d.Apply(b, Sync))
+
+	seq, err := d.DurableState()
+	require.NoError(t, err)
+	require.Greater(t, seq, base.SeqNum(0))
+
+	require.NoError(t, d.WaitForDurability(seq))
+	require.NoError(t, d.WaitForDurability(0))
+
+	stats = d.DurabilityStats()
+	require.Equal(t, seq, stats.HighestDurableSeqNum)
+	require.Equal(t, uint64(1), stats.TotalDurableCommits)
